import logging
import os
import re

import yaml
from robot.output.pyloggingconf import RobotHandler
from robot.output.librarylogger import console

DEFAULT_LOG_FORMAT = 'logger<%(name)s>:%(message)s'
MAIN_CONFIG_KEY = 'LOG_TO_ROBOT_CONSOLE'
LOG_FORMAT_KEY = 'log_format'
LOGGER_NAME_key = 'logger_name'
LOG_MSG_FILTER_KEY = 'log_msg_filter'


def append_robot_console_handler(logger_name):
    """
    Sets up logger with given name to log it's records to console. It can be configured via yaml file, see
    ute_common_abstract_core.robot_console_redirecting_handler.add_robot_console_redirecting_handler_to_logger
    :param logger_name: name of logger to set up
    :return:
    """
    add_robot_console_redirecting_handler_to_logger(logger_name, get_console_logging_config())


def get_console_logging_config(conf_file=None):
    """
    Setup logging configuration from yaml file.

    Configuration file path is read either in conf_file or
    from environment variable TA_UE_LOG_CONFIG

    :param conf_file: Path to log config file. If given this will override the path in environment variable
    :return: None
    """
    if conf_file:
        path = conf_file
    elif os.getenv('UTE_UE_CONSOLE_LOG_CONFIG', None):
        path = os.getenv('UTE_UE_CONSOLE_LOG_CONFIG', None)
    else:
        return None

    if os.path.isfile(path):
        with open(path, 'rt') as f:
            config = yaml.safe_load(f.read())
        return config
    else:
        return None


def add_robot_console_redirecting_handler_to_logger(logger_name, logger_config_file):
    r"""
    Log handler used to log records to Robot console. Configurable via yaml file, example below:

    LOG_TO_ROBOT_CONSOLE:
        - logger_name: ue_ue.ue
            log_msg_filter:
                - reservation
                - reservation\d+
            log_format: %{name}:%{message}
        - logger_name: ute_ue.debug
            log_msg_filter:
                - UeCharacteristics

    :param logger_name: name of logger to add console handler to
    :param logger_config_file: config file containing filters by which log messages will be filtered
    """
    if logger_config_file is None or logger_name is None:
        return
    logger_config = logger_config_file[MAIN_CONFIG_KEY]
    if logger_config is None or not _is_logger_name_in_config(logger_config, logger_name):
        return
    logger = logging.getLogger(logger_name)
    for handler in logger.handlers:
        if isinstance(handler, RobotConsoleRedirectingHandler):
            break
    else:
        logger_config = _get_logger_config(logger_config, logger_name)
        handler = RobotConsoleRedirectingHandler(logger_config)
        log_format = logger_config.get(LOG_FORMAT_KEY, DEFAULT_LOG_FORMAT)
        handler.setFormatter(logging.Formatter(fmt=log_format))
        logger.addHandler(handler)


def _get_logger_config(logger_config, logger_name):
    for logger_dict in logger_config:
        if logger_dict.get(LOGGER_NAME_key, None) == logger_name:
            return logger_dict


def _is_logger_name_in_config(logger_config, logger_name):
    for logger_dict in logger_config:
        if logger_dict.get(LOGGER_NAME_key, None) == logger_name:
            return True
    return False


class RobotConsoleRedirectingHandler(RobotHandler):

    def __init__(self, config):
        r"""
        Log handler used to log records to Robot console. Configurable via yaml file, example below:

        LOG_TO_ROBOT_CONSOLE:
            - logger_name: ue_ue.ue
                log_msg_filter:
                    - reservation
                    - reservation\d+
                log_format: %{name}:%{message}
            - logger_name: ute_ue.debug
                log_msg_filter:
                    - UeCharacteristics

        :param config: LogHandler configuration
        """
        super(RobotConsoleRedirectingHandler, self).__init__()
        self._filter_list = self._change_filters_to_regexp(config)
        self._first_log = True

    @staticmethod
    def _change_filters_to_regexp(config):
        filters = []
        for log_msg_filter in config.get(LOG_MSG_FILTER_KEY, []):
            filters.append(re.compile(log_msg_filter))
        return filters

    def emit(self, record):
        """
        Conditionally emit the specified logging record.

        Emission depends on filters which may have been added to the handler.
        Wrap the actual emission of the record with acquisition/release of
        the I/O thread lock. Returns whether the filter passed the record for
        emission.
        """
        message, error = self._get_message(record)
        if error:
            return
        if self._filter_log(message):
            message = self.formatter.format(record)
            console(message)

    def _filter_log(self, msg):
        for log_msg_filter in self._filter_list:
            if log_msg_filter.search(msg):
                return True
        return False
